def choose_move(observation):
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (0, 0))
    environment = observation.get("environment_name", "resource_collection")
    grid_width = observation.get("grid_width", 1)
    grid_height = observation.get("grid_height", 1)

    def get_closest_target(targets):
        if not targets:
            return None
        return min(targets, key=lambda pos: abs(pos[0] - sx) + abs(pos[1] - sy))

    def move_towards(target):
        dx, dy = 0, 0
        if target:
            if target[0] > sx:
                dx = 1
            elif target[0] < sx:
                dx = -1
            if target[1] > sy:
                dy = 1
            elif target[1] < sy:
                dy = -1
        return dx, dy

    # Defensive checks for missing fields
    resources = observation.get("resources") or []
    unclaimed_cells = observation.get("unclaimed_cells") or []
    opponent_territory = observation.get("opponent_territory") or []

    if environment == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            target = (ox, oy)
            return list(move_towards(target))
        # Move to corner opposite of self position as a fallback
        corners = [[0, 0], [0, grid_height - 1], [grid_width - 1, 0], [grid_width - 1, grid_height - 1]]
        target_corner = get_closest_target(corners)
        return list(move_towards(target_corner))

    elif environment == "territory_control":
        targets = unclaimed_cells or opponent_territory
        target = get_closest_target(targets)
        if not target:
            # No targets, just stay put
            return [0, 0]
        return list(move_towards(target))
    else:
        # Resource collection or default
        target = get_closest_target(resources)
        if not target:
            # No resources found, move towards opponent with fallback
            dx = 0 if ox == sx else (1 if ox > sx else -1)
            dy = 0 if oy == sy else (1 if oy > sy else -1)
            return [dx, dy]
        return list(move_towards(target))

